      const fill = s.destroyed ? 'rgba(70,72,66,0.5)' : '#454940';
      const cap = s.destroyed ? 'rgba(160,150,40,0.4)' : '#d9c93a';
      const stripeDark = s.destroyed ? 'rgba(40,36,18,0.5)' : '#2b2812';
